// Required env vars: SUPABASE_URL, SUPABASE_SERVICE_KEY, ANTHROPIC_API_KEY
// Optional: YOUTUBE_API_KEY (enables richer metadata via Data API v3)

const body = $input.first().json;
const url = body.url || '';
const videoId = body.video_id || url.match(/(?:v=|youtu\.be\/|embed\/)([a-zA-Z0-9_-]{11})/)?.[1];

if (!videoId) {
  throw new Error('Missing video_id — could not extract from URL: ' + url);
}

// 1. Fetch oEmbed metadata (no API key required)
let title = '', channelName = '', thumbnailUrl = '';
try {
  const oEmbedRes = await fetch(
    `https://www.youtube.com/oembed?url=${encodeURIComponent(url)}&format=json`
  );
  if (oEmbedRes.ok) {
    const oe = await oEmbedRes.json();
    title = oe.title || '';
    channelName = oe.author_name || '';
    thumbnailUrl = `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`;
  }
} catch (e) {
  console.error('oEmbed fetch failed:', e.message);
}

// 2. Try to fetch transcript via YouTube timedtext API (works for many videos)
let transcript = '';
try {
  const transcriptRes = await fetch(
    `https://www.youtube.com/api/timedtext?lang=en&v=${videoId}`
  );
  if (transcriptRes.ok) {
    const xml = await transcriptRes.text();
    // Strip XML tags, decode entities
    transcript = xml
      .replace(/<[^>]+>/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 12000); // Claude Haiku context limit
  }
} catch (e) {
  console.error('Timedtext fetch failed:', e.message);
}

// 3. If YOUTUBE_API_KEY is set, enrich with Data API v3
const ytApiKey = process.env.YOUTUBE_API_KEY;
let durationSeconds = null;
if (ytApiKey) {
  try {
    const apiRes = await fetch(
      `https://www.googleapis.com/youtube/v3/videos?id=${videoId}&part=snippet,contentDetails&key=${ytApiKey}`
    );
    if (apiRes.ok) {
      const apiData = await apiRes.json();
      const item = apiData.items?.[0];
      if (item) {
        title = title || item.snippet?.title || '';
        channelName = channelName || item.snippet?.channelTitle || '';
        // Parse ISO 8601 duration (PT4M13S → 253 seconds)
        const dur = item.contentDetails?.duration || '';
        const m = dur.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
        if (m) {
          durationSeconds = (parseInt(m[1]||'0')*3600) + (parseInt(m[2]||'0')*60) + parseInt(m[3]||'0');
        }
      }
    }
  } catch (e) {
    console.error('YouTube Data API failed:', e.message);
  }
}

// 4. Insert initial row into Supabase
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('Missing SUPABASE_URL or SUPABASE_SERVICE_KEY env vars');
}

const insertRes = await fetch(`${supabaseUrl}/rest/v1/blog_cms_youtube_sources`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'apikey': supabaseKey,
    'Authorization': `Bearer ${supabaseKey}`,
    'Prefer': 'return=representation'
  },
  body: JSON.stringify({
    url,
    video_id: videoId,
    title,
    channel_name: channelName,
    thumbnail_url: thumbnailUrl,
    duration_seconds: durationSeconds,
    transcript: transcript || null,
    transcript_language: transcript ? 'en' : null,
    status: transcript ? 'transcribed' : 'imported',
    key_topics: [],
    suggested_wiki_terms: [],
    article_opportunities: []
  })
});

if (!insertRes.ok) {
  const err = await insertRes.text();
  throw new Error(`Supabase insert failed (${insertRes.status}): ${err.slice(0, 300)}`);
}

const [insertedRow] = await insertRes.json();
const sourceId = insertedRow.id;

return [{ json: { source_id: sourceId, video_id: videoId, title, channel_name: channelName, transcript_length: transcript.length, status: 'transcribed' } }];

// Analyze transcript with Claude Haiku → key_topics + article_opportunities
// Required: ANTHROPIC_API_KEY, SUPABASE_URL, SUPABASE_SERVICE_KEY

const { source_id, video_id, title, channel_name, transcript_length } = $input.first().json;

const apiKey = process.env.ANTHROPIC_API_KEY;
if (!apiKey) throw new Error('Missing ANTHROPIC_API_KEY env var');

// Re-fetch transcript from Supabase
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_KEY;

const rowRes = await fetch(
  `${supabaseUrl}/rest/v1/blog_cms_youtube_sources?id=eq.${source_id}&select=transcript,title,channel_name`,
  { headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` } }
);
const [row] = await rowRes.json();
const transcript = row?.transcript || '';
const videoTitle = row?.title || title || '(unknown)';

let keyTopics = [];
let articleOpportunities = [];
let contextSummary = '';

if (transcript.length > 100) {
  const prompt = `You are an editorial analyst. Analyze this YouTube transcript and extract structured insights for a blog content team.

Video: "${videoTitle}" by ${channel_name || 'Unknown channel'}

Transcript (first 8000 chars):
${transcript.slice(0, 8000)}

Return ONLY valid JSON with this exact structure:
{
  "key_topics": ["topic1", "topic2", "topic3", "topic4", "topic5"],
  "article_opportunities": ["angle1: description", "angle2: description", "angle3: description"],
  "context_summary": "2-3 sentence summary of the main argument and key insights"
}

key_topics: 4-6 short phrases (max 5 words each) covering the main themes.
article_opportunities: 3 specific blog angles this content suggests, formatted as "Angle title: brief description".
context_summary: What is the core argument and most actionable insight?`;

  try {
    const claudeRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 800,
        messages: [{ role: 'user', content: prompt }]
      })
    });

    if (claudeRes.ok) {
      const claudeData = await claudeRes.json();
      const text = claudeData.content?.[0]?.text || '';
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        keyTopics = parsed.key_topics || [];
        articleOpportunities = parsed.article_opportunities || [];
        contextSummary = parsed.context_summary || '';
      }
    }
  } catch (e) {
    console.error('Claude analysis failed:', e.message);
    // Continue — will save with empty topics but mark as analyzed
  }
} else {
  contextSummary = `No transcript available for "${videoTitle}". Topics extracted from title only.`;
  // Extract basic topics from title
  keyTopics = videoTitle
    .split(/[\s,\-–:]+/)
    .filter(w => w.length > 4)
    .slice(0, 5);
}

// Update Supabase row with analysis results
const updateRes = await fetch(
  `${supabaseUrl}/rest/v1/blog_cms_youtube_sources?id=eq.${source_id}`,
  {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      key_topics: keyTopics,
      article_opportunities: articleOpportunities,
      context_summary: contextSummary,
      status: 'analyzed',
      updated_at: new Date().toISOString()
    })
  }
);

if (!updateRes.ok) {
  const err = await updateRes.text();
  console.error(`Supabase update failed (${updateRes.status}): ${err}`);
}

return [{ json: { source_id, key_topics: keyTopics, article_opportunities: articleOpportunities, context_summary: contextSummary, status: 'analyzed' } }];
